WITH RECURSIVE x(top, part, qty) AS (
  SELECT parent_id, child_id, qty FROM bom
  UNION ALL SELECT x.top, b.child_id, x.qty * b.qty FROM x JOIN bom b ON b.parent_id = x.part
)
SELECT t.sku AS product, r.sku AS raw, SUM(x.qty) AS qty FROM x JOIN parts r ON r.part_id = x.part AND r.kind = 'raw' JOIN parts t ON t.part_id = x.top WHERE x.top IN (SELECT part_id FROM parts WHERE kind = 'assembly' AND part_id NOT IN (SELECT child_id FROM bom)) GROUP BY x.top, x.part ORDER BY t.sku, r.sku;

